function main(): void {
  const { values } = parseArgs({...});
  const repo = process.env.GITHUB_REPOSITORY ?? "";

  if ((values.conclusion ?? "") === "skipped") { console.error("...nothing ran by design..."); return; }

  const title = parseRunTitle(values["display-title"]);
  if (!title) { console.error("...unrecognised run title, not an Atomaton run this watcher can read; nothing to do"); return; }

  // Read the thread. A read that fails is a red run here (the signal), not a silent pass.
  let comments: DatedComment[];
  try {
    comments = ghPaginated<{ body?: string; created_at?: string }>("api", `repos/${repo}/issues/${title.number}/comments`)
      .map(c => ({ body: c.body ?? "", createdAt: c.created_at ?? "" }));
  } catch (e) { console.error(`::error::could not read the thread on #${n}: ${e}`); process.exitCode = 1; return; }

  if (!needsEnding(comments, values["run-started-at"], readers)) {
    console.error("the run posted its ending; nothing to do");
    return;
  }

  // post notice
  const body = missingEndingNotice(title.agent, values["run-url"] ?? "");
  const { code, stdout, stderr } = gh("issue", "comment", String(title.number), "--repo", repo, "--body", body);
  if (code !== 0) { console.error(`::error::...`); process.exitCode = 1; /* continue to label? no — return */ return; }

  // label release, best-effort
  const last = lastEndingComment(comments, readers);   // pre-notice ending ✓ (comments read BEFORE posting)
  if (getLabelPresent(...) && releasesLabel(last, readers)) { remove label best-effort }
}
```

